import { z } from 'zod';
import { Provider } from './knowledge.js';

/**
 * Onboarding Tour (SPEC-11): a five-section tour of a repository, generated by
 * one model request in the background. `Tour` is the stored document,
 * `TourRead` is what GET /repos/:id/onboarding returns, `TourGeneration` is the
 * persisted generation state.
 */

export const TourSectionKind = z.enum([
  'architecture_overview',
  'critical_paths',
  'how_to_run',
  'guided_reading',
  'first_tasks',
]);
export type TourSectionKind = z.infer<typeof TourSectionKind>;

/** The five kinds in the order a tour shows them. */
export const TOUR_SECTION_KINDS = [
  'architecture_overview',
  'critical_paths',
  'how_to_run',
  'guided_reading',
  'first_tasks',
] as const satisfies readonly TourSectionKind[];

export const TOUR_LIMITS = {
  criticalPaths: 8,
  guidedReading: 8,
  howToRun: 8,
  firstTasks: 3,
  overviewChars: 1200,
} as const;

export const TourComplexity = z.enum(['low', 'medium', 'high']);
export type TourComplexity = z.infer<typeof TourComplexity>;

export const ArchitectureOverviewSection = z.object({
  kind: z.literal('architecture_overview'),
  body: z.string().max(TOUR_LIMITS.overviewChars),
  diagram: z.string().nullable(), // mermaid
});
export type ArchitectureOverviewSection = z.infer<typeof ArchitectureOverviewSection>;

export const CriticalPathsSection = z.object({
  kind: z.literal('critical_paths'),
  files: z
    .array(z.object({ path: z.string(), note: z.string() }))
    .max(TOUR_LIMITS.criticalPaths),
});
export type CriticalPathsSection = z.infer<typeof CriticalPathsSection>;

export const HowToRunSection = z.object({
  kind: z.literal('how_to_run'),
  steps: z
    .array(z.object({ command: z.string(), source: z.string() }))
    .max(TOUR_LIMITS.howToRun),
});
export type HowToRunSection = z.infer<typeof HowToRunSection>;

export const GuidedReadingSection = z.object({
  kind: z.literal('guided_reading'),
  reading: z
    .array(z.object({ path: z.string(), why: z.string() }))
    .max(TOUR_LIMITS.guidedReading),
});
export type GuidedReadingSection = z.infer<typeof GuidedReadingSection>;

export const FirstTasksSection = z.object({
  kind: z.literal('first_tasks'),
  tasks: z
    .array(z.object({ title: z.string(), scope: z.string(), complexity: TourComplexity }))
    .max(TOUR_LIMITS.firstTasks),
});
export type FirstTasksSection = z.infer<typeof FirstTasksSection>;

export const Tour = z.object({
  repo_id: z.string().uuid(),
  generated_at: z.string(),
  commit_sha: z.string(),
  files_indexed: z.number().int().nonnegative(),
  limited_index: z.boolean(),
  provider: Provider,
  model: z.string(),
  tokens_in: z.number().int().nonnegative(),
  tokens_out: z.number().int().nonnegative(),
  cost_usd: z.number().nullable(),
  dropped_items: z.number().int().nonnegative(),
  sections: z.tuple([
    ArchitectureOverviewSection,
    CriticalPathsSection,
    HowToRunSection,
    GuidedReadingSection,
    FirstTasksSection,
  ]),
});
export type Tour = z.infer<typeof Tour>;

export const TourGeneration = z.object({
  status: z.enum(['idle', 'running', 'failed']),
  started_at: z.string().nullable(),
  error: z.string().nullish(),
});
export type TourGeneration = z.infer<typeof TourGeneration>;

export const TourRead = z.object({
  tour: Tour.nullable(),
  generation: TourGeneration,
});
export type TourRead = z.infer<typeof TourRead>;

export const TourGenerationStarted = z.object({
  generation: TourGeneration,
});
export type TourGenerationStarted = z.infer<typeof TourGenerationStarted>;
